    #[test]
    fn hair_style_lookup() {
        assert_eq!(resolve_head_id(Sex::Male, Some(0)), 2);
        assert_eq!(resolve_head_id(Sex::Male, Some(1)), 2);
        assert_eq!(resolve_head_id(Sex::Male, Some(3)), 7);
        assert_eq!(resolve_head_id(Sex::Male, Some(12)), 11);
        assert_eq!(resolve_head_id(Sex::Female, Some(0)), 2);
        assert_eq!(resolve_head_id(Sex::Female, Some(2)), 4);
        assert_eq!(resolve_head_id(Sex::Female, Some(12)), 8);
        assert_eq!(resolve_head_id(Sex::Male, Some(20)), 20, "out-of-table ids pass through");
        assert_eq!(resolve_head_id(Sex::Female, None), 1, "missing hair style uses the default");
        assert_eq!(resolve_head_id(Sex::Server, Some(4)), 1);
    }

