    fn load_game_file_loader() -> GameFileLoader {
        let game_file_loader = GameFileLoader::default();
        game_file_loader.load_archives_from_settings();

        let lua_archive_existed = std::path::Path::new("lua_files.7z").exists();
        game_file_loader.load_patched_lua_files();

        if !lua_archive_existed {
            game_file_loader.remove_patched_lua_files();
        }

        game_file_loader
    }

    /// The `--check-appearance` audit against the real archives.
    ///
    /// This replaces the previously ignored `job_audit` test: it validates
    /// every job/body/hair/palette/headgear sprite of the data file against the
    /// archives and additionally covers the job list fixture (so a job added to
    /// the server without a data row is caught).
    #[test]
    #[ignore = "requires the game archives (run from the korangar crate root, client/game_archives.ron)"]
    fn every_server_job_has_a_sprite_palette_and_skill_tree() {
        let game_file_loader = load_game_file_loader();
        let report = check_appearance(&game_file_loader).expect("appearance audit");

        assert_eq!(report.jobs, 181);
        assert!(report.jobs_with_both_sexes >= 160, "both-sex body coverage: {report:?}");
        assert_eq!(report.embedded_palettes, 16, "documented embedded-palette jobs");
        assert!(report.hair_styles >= 13, "hair styles validated: {report:?}");
        assert_eq!(report.headgear, 1365, "headgear sprites validated: {report:?}");
        assert_eq!(report.headgear_without_sprite, 161, "documented missing headgear: {report:?}");
        assert!(
            report.jobs_without_identity.len() <= 27,
            "unexpected number of jobs without JobIdentity: {:?}",
            report.jobs_without_identity
        );

        // Cross-check the server job fixture: every real job id of the fixture
        // has a registry row and is classified as a player.
        const JOB_IDS: &str = include_str!("library/test_data/job_ids.txt");
        const SENTINEL_JOB_IDS: [u16; 2] = [31, 4317];
        for line in JOB_IDS.lines() {
            let line = line.trim();
            if line.is_empty() || line.starts_with('#') {
                continue;
            }
            let id = JobId(line.split('\t').next().unwrap().parse().expect("malformed job id"));
            if SENTINEL_JOB_IDS.contains(&id.0) {
                assert!(profile(id).is_none(), "sentinel job {id:?} must not have a row");
                continue;
            }
            assert!(profile(id).is_some(), "job fixture id {id:?} has no registry row");
            assert_eq!(EntityType::from(id), EntityType::Player, "job {id:?}");
        }
    }
    #[test]
    fn appearance_job_applies_outfits_and_mounts() {
        // Normal jobs keep their body.
        assert_eq!(appearance_job(JobId(1), 0), JobId(1));
        // Knight -> Peco (classic riding pair 7 -> 13).
        assert_eq!(appearance_job(JobId(7), OPTION_RIDING), JobId(13));
        // Wedding / Xmas / summer / hanbok / Oktoberfest outfits.
        assert_eq!(appearance_job(JobId(7), OPTION_WEDDING), JobId(22));
        assert_eq!(appearance_job(JobId(7), OPTION_XMAS), JobId(26));
        assert_eq!(appearance_job(JobId(7), OPTION_SUMMER), JobId(27));
        assert_eq!(appearance_job(JobId(7), OPTION_HANBOK), JobId(28));
        assert_eq!(appearance_job(JobId(7), OPTION_OKTOBERFEST), JobId(29));
        // A union outfit is ignored (union overrides holiday outfits).
        assert_eq!(appearance_job(JobId(7), OPTION_UNION | OPTION_XMAS), JobId(7));
        // Unmounted jobs stay unchanged by a riding bit.
        assert_eq!(appearance_job(JobId(1), OPTION_RIDING), JobId(1));
        assert!(is_outfit_job(JobId(22)) && !is_outfit_job(JobId(7)));
    }

    #[test]
    fn cart_paths_follow_the_classic_cart_rules() {
        assert_eq!(
            cart_paths(JobId(7), 1),
            (r"이팩트\손수레".to_owned(), r"이팩트\손수레".to_owned())
        );
        assert_eq!(
            cart_paths(JobId(7), 2),
            (r"이팩트\손수레1".to_owned(), r"이팩트\손수레1".to_owned())
        );
        assert_eq!(
            cart_paths(JobId(7), 10),
            (r"이팩트\선물상자카트".to_owned(), r"이팩트\선물상자카트".to_owned())
        );
        // Super Novice uses its own cart regardless of type.
        assert_eq!(
            cart_paths(JobId(23), 3),
            (r"이팩트\슈노손수레".to_owned(), r"이팩트\슈노손수레".to_owned())
        );
        // A baby's default cart uses the baby ACT with the grown-up sprite.
        assert_eq!(
            cart_paths(JobId(4023), 1),
            (r"이팩트\손수레".to_owned(), r"이팩트\베이비손수레".to_owned())
        );
        // Numbered baby carts from type 6 have their own sprite/ACT.
        assert_eq!(
            cart_paths(JobId(4023), 6),
            (r"이팩트\손수레5베이비".to_owned(), r"이팩트\손수레5베이비".to_owned())
        );
    }
